const inp = msg.payload;

// Define which fields you want in the series
const series = ["Vac1"];

let outObj = [{
    series: series,
    data: series.map(() => []),  // create an empty array for each series
    labels: [""]
}];

// Loop through data objects (data1, data2, ...)
let i = 0;
for (let key in inp) {
    if (key.startsWith("data")) {
        let item = inp[key];
        let timestamp = Date.now() + i * 1000;  // fake timestamp (1s apart)

        series.forEach((field, idx) => {
            if (item[field] !== undefined) {
                outObj[0].data[idx].push({
                    x: timestamp,
                    y: item[field]
                });
            }
        });
        i++;
    }
}

msg.payload = outObj;
return msg;

