// Expecting msg.payload to be an array with one series (Vac1)
const chartData = msg.payload;

let yValues = [];

if (Array.isArray(chartData) && chartData.length > 0 && chartData[0]?.data?.[0]) {
    const points = chartData[0].data[0]; // array of { x, y }
    if (Array.isArray(points)) {
        yValues = points
            .map(p => Number(p?.y))
            .filter(v => Number.isFinite(v));
    }
}

// Average all y values
const avgRaw = yValues.length
    ? yValues.reduce((sum, v) => sum + v, 0) / yValues.length
    : 0;

// Round to 2 decimals and keep it as a number
const avgY = Math.round(avgRaw * 100) / 100;

msg.payload = avgY;
return msg;

